INSERT INTO `v1_344aac91ceec67d1c4e2bcf79cc078304466179093e9022834bbb06145311d07` VALUES ("105811_01", 0, "ミッションに挑戦できますよっ♪\n早速出かけましょう～！", 105801);
INSERT INTO `v1_344aac91ceec67d1c4e2bcf79cc078304466179093e9022834bbb06145311d07` VALUES ("105911_01", 1, "主さま、本日はこのミッションに\n挑戦してみましょう。", 105901);
INSERT INTO `v1_344aac91ceec67d1c4e2bcf79cc078304466179093e9022834bbb06145311d07` VALUES ("106011_01", 2, "ミッションに挑戦できるみたい。\nせっかくだしやってみたら？", 106001);
INSERT INTO `v1_344aac91ceec67d1c4e2bcf79cc078304466179093e9022834bbb06145311d07` VALUES ("106411_01", 3, "ねえ、今日はこのミッションに\n挑戦してみない？", 106401);
